def ema_series(values,alpha):
    x=np.asarray(values,dtype=np.float64)
    if x.ndim!=1 or not np.all(np.isfinite(x)) or not np.isfinite(alpha) or not 0<alpha<=1:
        raise ValueError("invalid values or alpha")
